def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    yesterday_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 140:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(float(prev['bid']))

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 42.0))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45
    if day >= 8:
        urgency += 0.2

    pressure = 0.0
    if highest_prev >= 180:
        pressure = 1.0
    elif highest_prev >= 130:
        pressure = 0.75
    elif highest_prev >= 80:
        pressure = 0.45
    elif highest_prev > 0:
        pressure = 0.2

    base = 20.0 + 18.0 * scarcity + 8.0 * min(len(alive_opponents), 3)

    if urgency >= 1.4:
        bid = max(base + 35.0, highest_prev * 0.72 + 6.0, 78.0 + 18.0 * scarcity)
    elif urgency >= 0.7:
        bid = max(base + 12.0, avg_prev * 0.55 + 4.0, 48.0 + 14.0 * scarcity)
    else:
        if pressure >= 0.75 and hp > 4 and no_water_days == 0:
            bid = 16.0 + 10.0 * scarcity
        elif pressure >= 0.45:
            bid = max(28.0 + 10.0 * scarcity, min(highest_prev + 2.0, 72.0))
        else:
            bid = base

    if desperate_count >= 2:
        bid += 10.0
    elif desperate_count == 0 and rich_count >= 2 and urgency < 0.7:
        bid -= 6.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.6

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 1.4:
        max_affordable = budget
    elif max_affordable <= 0:
        max_affordable = min(budget, 25.0 if hp > 3 else 55.0)

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 85.0 + 20.0 * scarcity))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents alive, conserve
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = DAILY_SALARY * 0.6

    # Supply tightness: fewer total units means higher chance of losing allocation
    # If supply >= 2*WATER_REQ, one unit likely available per winner; otherwise tighter.
    units = supply / float(WATER_REQ)
    tight = 1.0 if units < 2.0 else 0.0

    # Risk from our own HP/no-water streak
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Base bid targeting just enough to beat typical winners without matching their high spend.
    # Use avg_prev_bid as anchor; add a small premium when tight or when we are at risk.
    premium = 0.0
    if tight > 0.0:
        premium += 12.0
    if no_water_days >= 2:
        premium += 18.0
    if hp <= 3.0:
        premium += 25.0

    # If yesterday pressure was extremely high, we must respond more.
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        premium += 10.0

    target = avg_prev_bid + premium

    # Keep target under a fraction of their highest to avoid overspending.
    # If we are desperate, allow approaching highest_prev_bid.
    if hp <= 2.0 or no_water_days >= 3:
        cap = min(highest_prev_bid * 0.98 if highest_prev_bid > 0 else DAILY_SALARY * 0.95, DAILY_SALARY * 1.0)
    else:
        cap = min(highest_prev_bid * 0.92 if highest_prev_bid > 0 else DAILY_SALARY * 0.8, DAILY_SALARY * 0.85)

    bid = min(target, cap)

    # Also ensure we don't exceed budget
    if bid > budget:
        bid = budget

    # Never bid negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

